package sg.safelease.app;

import android.app.AlertDialog;
import android.content.*;
import android.content.pm.*;
import android.net.Uri;
import android.os.*;
import java.io.*;
import java.net.*;
import java.security.MessageDigest;
import java.util.*;
import java.util.concurrent.*;
import java.util.concurrent.atomic.AtomicBoolean;
import org.json.JSONObject;

/** No installer privilege is assumed: Android retains the user's installation confirmation. */
final class AppUpdater {
 static final String MANIFEST="https://github.com/Quietime/safelease-releases/releases/latest/download/update.json";
 static final int INSTALL_REQUEST=902,PERMISSION_REQUEST=903;
 static final long MAX_BYTES=100L*1024*1024;
 final MainActivity owner;final android.content.SharedPreferences prefs;
 final ExecutorService worker=Executors.newSingleThreadExecutor();final AtomicBoolean busy=new AtomicBoolean();
 volatile JSONObject metadata;volatile String state="idle",errorCode="";volatile int progress;volatile boolean active,ready,closed,installLaunching,awaitPermission;
 long checkedAt;final Handler handler=new Handler(Looper.getMainLooper());
 AppUpdater(MainActivity activity){owner=activity;prefs=activity.getSharedPreferences("updates",0);try{String stored=prefs.getString("download_meta",null);if(stored!=null){metadata=new JSONObject(stored);if(version()>=metadata.getLong("versionCode"))cleanupInstalled();else if(file(metadata).isFile())state="ready";}}catch(Exception e){state="failed";}
  File dir=directory();File[] files=dir.listFiles();if(files!=null)for(File f:files)if(f.getName().endsWith(".part"))f.delete();
 }
 String tr(String en,String zh){return "zh".equals(owner.pref("language"))?zh:en;}
 long version(){try{return owner.getPackageManager().getPackageInfo(owner.getPackageName(),0).getLongVersionCode();}catch(Exception e){return 0;}}
 String versionName(){try{return owner.getPackageManager().getPackageInfo(owner.getPackageName(),0).versionName;}catch(Exception e){return "";}}
 File directory(){File d=new File(owner.getFilesDir(),"updates");d.mkdirs();return d;}
 File file(JSONObject m)throws Exception{return new File(directory(),"update-v"+m.getLong("versionCode")+".apk");}
 boolean option(String name){return prefs.getBoolean(name,true);}
 String preferences(){try{return new JSONObject().put("autoCheck",option("autoCheck")).put("autoDownload",option("autoDownload")).put("autoInstall",option("autoInstall")).toString();}catch(Exception e){return "{}";}}
 void preference(String key,boolean value){if(Arrays.asList("autoCheck","autoDownload","autoInstall").contains(key))prefs.edit().putBoolean(key,value).apply();}
 String status(){try{return new JSONObject().put("state",state).put("errorCode",errorCode).put("progress",progress).put("versionName",metadata!=null&&metadata.optLong("versionCode")>version()?metadata.optString("versionName"):"").put("currentVersion",versionName()).put("currentVersionCode",version()).put("packageRemoved",prefs.getBoolean("package_removed",false)).put("installedUpdateCode",prefs.getLong("installed_update",0)).put("manifestUrl",MANIFEST).toString();}catch(Exception e){return "{}";}}
 void appReady(){ready=true;startup();}
 void startup(){if(ready&&option("autoCheck")&&System.currentTimeMillis()-checkedAt>60000)check();}
 void resume(){active=true;if(awaitPermission&&owner.getPackageManager().canRequestPackageInstalls()){awaitPermission=false;install(false);}else{startup();if("ready".equals(state))handler.post(()->maybeInstall(0));}}
 void pause(){active=false;}
 void close(){closed=true;handler.removeCallbacksAndMessages(null);worker.shutdownNow();}
 void action(String action){if("check".equals(action))check();else if("download".equals(action))download();else if("install".equals(action))handler.post(()->install(false));}
 void check(){if(!busy.compareAndSet(false,true))return;errorCode="";state="checking";checkedAt=System.currentTimeMillis();worker.execute(()->{try{JSONObject m;try(InputStream in=open(new URL(MANIFEST+"?installed="+version()+"&check="+System.currentTimeMillis())).getInputStream()){m=new JSONObject(new String(read(in,32768),java.nio.charset.StandardCharsets.UTF_8));}validateMetadata(m,owner.getPackageName(),Build.VERSION.SDK_INT);if(m.getLong("versionCode")<=version()){state="current";metadata=null;}else{metadata=m;state="available";}}catch(Exception e){errorCode=code(e);state="failed";android.util.Log.w("SafeLeaseUpdate","check_failed: "+errorCode);}finally{busy.set(false);}if("available".equals(state)&&option("autoDownload")&&!closed)download();});}
 void download(){final JSONObject m=metadata;if(m==null||busy.getAndSet(true))return;state="downloading";progress=0;worker.execute(()->{File part=null;try{validateMetadata(m,owner.getPackageName(),Build.VERSION.SDK_INT);File target=file(m);if(!target.isFile()){part=new File(directory(),target.getName()+".part");HttpURLConnection connection=open(new URL(m.getString("downloadUrl")));try(InputStream in=connection.getInputStream();FileOutputStream out=new FileOutputStream(part)){long total=0,expected=m.getLong("size");byte[] bytes=new byte[32768];int n;while((n=in.read(bytes))!=-1){if(Thread.currentThread().isInterrupted())throw new InterruptedIOException();total+=n;if(total>expected||total>MAX_BYTES)throw new IOException("download_size");out.write(bytes,0,n);progress=(int)(total*100/expected);}if(total!=expected)throw new IOException("incomplete_download");out.getFD().sync();}finally{connection.disconnect();}verifyArchive(owner,part,owner.getPackageName(),m.getLong("versionCode"),m.getString("sha256"),ownSigner());java.nio.file.Files.move(part.toPath(),target.toPath(),java.nio.file.StandardCopyOption.ATOMIC_MOVE,java.nio.file.StandardCopyOption.REPLACE_EXISTING);part=null;}else verifyArchive(owner,target,owner.getPackageName(),m.getLong("versionCode"),m.getString("sha256"),ownSigner());prefs.edit().putString("download_meta",m.toString()).putBoolean("package_removed",false).commit();state="ready";progress=100;handler.post(()->maybeInstall(0));}catch(Exception e){if(part!=null)part.delete();errorCode=code(e);state="failed";android.util.Log.w("SafeLeaseUpdate","download_rejected: "+errorCode);}finally{busy.set(false);}});}
 void maybeInstall(int attempt){if(closed||!option("autoInstall")||metadata==null||!"ready".equals(state)||prefs.getLong("auto_offered",0)==metadata.optLong("versionCode"))return;if(!active||!ready)return;owner.web.evaluateJavascript("window.AndroidUI&&AndroidUI.canInstall()",value->{if(closed)return;if("true".equals(value)){install(true);}else if(attempt<12)handler.postDelayed(()->maybeInstall(attempt+1),5000);});}
 void install(boolean automatic){if(closed||installLaunching||metadata==null)return;try{File apk=file(metadata);if(!apk.isFile()||metadata.getLong("versionCode")<=version())return;verifyArchive(owner,apk,owner.getPackageName(),metadata.getLong("versionCode"),metadata.getString("sha256"),ownSigner());if(automatic){if(prefs.getLong("auto_offered",0)==metadata.getLong("versionCode"))return;prefs.edit().putLong("auto_offered",metadata.getLong("versionCode")).apply();}if(!owner.getPackageManager().canRequestPackageInstalls()){state="permission";new AlertDialog.Builder(owner).setTitle(tr("Allow app updates","允许应用更新")).setMessage(tr("Android needs your permission before this app can open the update installer.","Android需要你允许此应用发起更新安装。")).setPositiveButton(tr("Open settings","打开设置"),(dialog,which)->{awaitPermission=true;owner.startActivityForResult(new Intent(android.provider.Settings.ACTION_MANAGE_UNKNOWN_APP_SOURCES,Uri.parse("package:"+owner.getPackageName())),PERMISSION_REQUEST);}).setNegativeButton(tr("Later","稍后"),null).show();return;}
  installLaunching=true;state="installing";Uri uri=Uri.parse("content://"+owner.getPackageName()+".updates/"+apk.getName());Intent intent=new Intent(Intent.ACTION_INSTALL_PACKAGE).setData(uri).setFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION).putExtra(Intent.EXTRA_RETURN_RESULT,true);owner.startActivityForResult(intent,INSTALL_REQUEST);
 }catch(Exception e){installLaunching=false;errorCode=code(e);state="failed";android.util.Log.w("SafeLeaseUpdate","install_failed: "+errorCode);}}
 void activityResult(int request){if(request==PERMISSION_REQUEST){if(owner.getPackageManager().canRequestPackageInstalls()){awaitPermission=false;install(false);}else state="permission";}else if(request==INSTALL_REQUEST){installLaunching=false;try{if(metadata!=null&&version()>=metadata.getLong("versionCode"))cleanupInstalled();else state="cancelled";}catch(Exception e){state="failed";}}}
 void cleanupInstalled()throws Exception{if(metadata==null||version()<metadata.getLong("versionCode"))return;File apk=file(metadata);boolean existed=apk.exists(),removed=!existed||apk.delete();if(!removed){state="failed";return;}prefs.edit().remove("download_meta").remove("auto_offered").putLong("installed_update",version()).putBoolean("package_removed",true).commit();android.util.Log.i("SafeLeaseUpdate","cleanup_success version="+version()+" existed="+existed+" removed="+removed);metadata=null;state="updated";}
 static String code(Exception e){String message=e.getMessage();return message!=null&&message.matches("[a-z_]+[0-9_]*")?message:e instanceof SecurityException?"verification_failed":"network_or_storage_error";}
 String ownSigner()throws Exception{PackageInfo info=owner.getPackageManager().getPackageInfo(owner.getPackageName(),PackageManager.GET_SIGNING_CERTIFICATES);return signer(info);}
 static String signer(PackageInfo info)throws Exception{if(info.signingInfo==null||info.signingInfo.getApkContentsSigners().length!=1)throw new SecurityException("signer_count");return digest(info.signingInfo.getApkContentsSigners()[0].toByteArray());}
 static String digest(byte[] bytes)throws Exception{return hex(MessageDigest.getInstance("SHA-256").digest(bytes));}
 static String hex(byte[] bytes){StringBuilder s=new StringBuilder();for(byte b:bytes)s.append(String.format(Locale.ROOT,"%02x",b&255));return s.toString();}
 static void validateMetadata(JSONObject m,String packageName,int sdk)throws Exception{if(m.getInt("schema")!=1||!packageName.equals(m.getString("packageName")))throw new SecurityException("package_name");if(m.getLong("versionCode")<1||m.getLong("size")<1||m.getLong("size")>MAX_BYTES||!m.getString("sha256").matches("[a-f0-9]{64}")||m.getInt("minSdk")>sdk)throw new SecurityException("manifest_values");URL u=new URL(m.getString("downloadUrl"));validateUrl(u);if(!"github.com".equals(u.getHost())||!u.getPath().startsWith("/Quietime/safelease-releases/releases/download/"))throw new SecurityException("download_origin");}
 static void validateUrl(URL u)throws Exception{String host=u.getHost().toLowerCase(Locale.ROOT);if(!"https".equals(u.getProtocol())||u.getUserInfo()!=null||(u.getPort()!=-1&&u.getPort()!=443)||!Arrays.asList("github.com","release-assets.githubusercontent.com","objects.githubusercontent.com").contains(host))throw new SecurityException("https_origin");}
 static HttpURLConnection open(URL source)throws Exception{URL url=source;for(int i=0;i<6;i++){validateUrl(url);HttpURLConnection c=(HttpURLConnection)url.openConnection();c.setConnectTimeout(12000);c.setReadTimeout(25000);c.setInstanceFollowRedirects(false);c.setUseCaches(false);c.setRequestProperty("Cache-Control","no-cache");c.setRequestProperty("User-Agent","SafeLease-Android-Updater");int status=c.getResponseCode();if(status>=300&&status<400){String location=c.getHeaderField("Location");c.disconnect();if(location==null)throw new IOException("redirect_missing");url=new URL(url,location);continue;}if(status!=200){c.disconnect();throw new IOException("http_"+status);}return c;}throw new IOException("redirect_limit");}
 static byte[] read(InputStream in,int max)throws Exception{ByteArrayOutputStream out=new ByteArrayOutputStream();byte[] b=new byte[4096];int n;while((n=in.read(b))!=-1){if(out.size()+n>max)throw new IOException("body_limit");out.write(b,0,n);}return out.toByteArray();}
 static void verifyArchive(Context context,File apk,String packageName,long version,String sha,String certificate)throws Exception{MessageDigest hash=MessageDigest.getInstance("SHA-256");try(InputStream in=new FileInputStream(apk)){byte[] bytes=new byte[32768];int n;while((n=in.read(bytes))!=-1)hash.update(bytes,0,n);}if(!MessageDigest.isEqual(hex(hash.digest()).getBytes(java.nio.charset.StandardCharsets.US_ASCII),sha.getBytes(java.nio.charset.StandardCharsets.US_ASCII)))throw new SecurityException("checksum");PackageInfo info=context.getPackageManager().getPackageArchiveInfo(apk.getAbsolutePath(),PackageManager.GET_SIGNING_CERTIFICATES);if(info==null||!packageName.equals(info.packageName)||info.getLongVersionCode()!=version||!certificate.equals(signer(info))||info.applicationInfo.minSdkVersion>Build.VERSION.SDK_INT)throw new SecurityException("apk_identity");}
}
